const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Antarctica region (approximate bounding box)
  const antarctica = ee.Geometry.Rectangle([-180, -90, 180, -60]);

  // Define time period for 2021 ozone hole season (August-October)
  const startDate = '2021-08-01';
  const endDate = '2021-10-31';

  // Get OMI ozone data
  const ozoneCol = ee.ImageCollection('NASA/OMI/DATA_MONTHLY')
    .filterDate(startDate, endDate)
    .filterBounds(antarctica)
    .select('ColumnAmountO3');

  // Check if collection has data
  const colSize = ozoneCol.size().getInfo();
  console.log(`2021 Ozone images: ${colSize}`);

  if (colSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate monthly ozone hole areas and find maximum
  const monthlyAreas = [];
  const months = ['Aug', 'Sep', 'Oct'];

  for (let i = 0; i < colSize; i++) {
    const img = ee.Image(ozoneCol.toList(colSize).get(i));
    const date = img.date().format('YYYY-MM').getInfo();

    // Define ozone hole as areas with ozone < 220 Dobson Units
    const ozoneHole = img.lt(220);

    // Calculate area in square kilometers
    const areaStats = ozoneHole.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: antarctica,
      scale: 25000,  // 25km scale for ozone data
      maxPixels: 1e9
    });

    const pixelArea = areaStats.get('ColumnAmountO3').getInfo();

    if (pixelArea === null) {
      console.log(`No valid pixels for ${date}`);
      monthlyAreas.push(0);
      continue;
    }

    // Convert pixel count to area (assuming 25km pixels)
    const areaKm2 = pixelArea * 625;  // 25km × 25km = 625 km² per pixel
    const areaMillionKm2 = areaKm2 / 1e6;

    console.log(`${date}: ${areaMillionKm2.toFixed(2)} million km²`);
    monthlyAreas.push(areaMillionKm2);
  }

  if (monthlyAreas.length === 0) {
    console.log("No valid ozone hole calculations");
    console.log("<answer>C2</answer>");
    return;
  }

  // Find maximum ozone hole area in 2021
  const maxArea = Math.max(...monthlyAreas);
  console.log(`Max ozone hole area 2021: ${maxArea.toFixed(2)} million km²`);
  console.log(`Target: 18.00 million km²`);

  // Validate result
  if (maxArea === null || maxArea === undefined || isNaN(maxArea) || maxArea < 0) {
    console.log("<answer>C3</answer>");
  } else if (maxArea >= 18.0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
